     * @return The next position
     */
    fun subscribePosition(): Flow<Position> = callbackFlow {
        val subscriptionHandle = native.subscribePosition() { value -> trySend(value) }
        awaitClose { native.unsubscribePosition(subscriptionHandle) }
    }

